"""Render a readable benchmark alongside the machine-readable training report."""


def markdown_report(report: dict) -> str:
    split = report["split"]
    lines = [
        "# Reproduced benchmark",
        "",
        "Generated by `python model_train.py`. Values below come from the same run as "
        "the adjacent JSON report and model artifact.",
        "",
        f"**Data:** {report['dataset']['rows']:,} accounts, "
        f"{report['dataset']['features']} features, "
        f"{report['dataset']['churn_rate']:.1%} observed churn.",
        "",
        f"**Split:** {split['train_rows']:,} training / {split['test_rows']:,} holdout accounts; "
        f"{split['test_churn_count']:,} holdout churners; "
        f"stratified by churn, seed {split['seed']}.",
        "",
        "**Threshold policy:** " + report["threshold_policy"] + ". "
        "The holdout is excluded from fitting and threshold selection.",
        "",
        "| Model | Threshold | Average precision | ROC AUC | Recall | Precision | "
        "Flagged | Missed churners |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for name, result in report["models"].items():
        lines.append(
            f"| {name} | {result['threshold']:.0%} | {result['average_precision']:.3f} | "
            f"{result['roc_auc']:.3f} | {result['recall']:.1%} | {result['precision']:.1%} | "
            f"{result['flagged_customers']:,} | {result['false_negatives']:,} |"
        )
    model_name = report["demo_model"]
    demo = report["models"][model_name]
    tn, fp = demo["confusion_matrix"][0]
    fn, tp = demo["confusion_matrix"][1]
    lines.extend(
        [
            "",
            "## Demo model",
            "",
            f"{model_name} is retained to explore the original four-class research question. "
            "This designation is set before viewing holdout results.",
            "",
            "| Actual / predicted | No review | Review |",
            "| --- | ---: | ---: |",
            f"| No churn | {tn:,} | {fp:,} |",
            f"| Churn | {fn:,} | {tp:,} |",
            "",
            f"The review queue contains {tp:,} churners and {fp:,} false alerts. "
            f"Four-class argmax accuracy is {report['four_class']['accuracy']:.1%}; "
            "it uses a different decision rule from the binary review threshold above.",
            "",
            f"The observed-value cutoff is **${report['value_threshold']:,.3f}** "
            "in historical charges, "
            "learned from the training partition. Missing historical charges are assigned to "
            "the lower observed-value tier; numeric model inputs use training-median imputation.",
            "",
            "## Historical-charge diagnostic",
            "",
            f"Missed churners account for **${demo['missed_churn_historical_charges']:,.2f}** "
            f"in recorded historical charges ({demo['missed_charge_share']:.1%} of the "
            "holdout churners' recorded charges). This is an exposure proxy. It does not "
            "estimate future revenue loss, retention uplift, or revenue saved.",
            "",
            "## Reproducibility",
            "",
            f"Dataset SHA-256: `{report['dataset']['sha256']}`.",
            "",
            "The JSON report records dependency versions, split fingerprints, binary "
            "and four-class confusion matrices, F-scores, and Brier scores. "
            "See [the model card](../docs/model-card.md) for interpretation and limitations.",
            "",
        ]
    )
    return "\n".join(lines)
